/* One power intent for keyboard, touch and gamepad; resources are paid at action startup. */
(function(root){
  'use strict';
  const C=(v,a=0,b=1)=>Math.max(a,Math.min(b,v)),ELEMENTS=['fire','water','earth','wind','lightning','stretch'];
  const CASTS={fire:['4','e'],water:['7','k'],earth:['2','l'],wind:['W','Z'],lightning:['E','Q'],stretch:['S','R']};
  const LABELS={fire:['Ember shot','Dragon breath'],water:['Water dart','Water current'],earth:['Fault launch','Raise terrace'],wind:['Wind palm','Cyclone'],lightning:['Chain spark','Thunderclap'],stretch:['Elastic straight','Reel / catch']};
  class PowerControl{
    constructor(world){this.world=world;this.selected=ELEMENTS.includes(world.powerElement)?world.powerElement:'fire';this.charge=null;this.aim={active:false,point:null};this.throwHeld=false;}
    blocked(){const w=this.world,f=w.player;return w.over||w.run?.blocked()||w.boss?.blocked()||f.ko||f.held||f.down>0||f.stunned>0||f.balloon||f.dodge;}
    select(element){if(!ELEMENTS.includes(element))return false;this.cancel();this.selected=element;this.world.powerElement=element;this.world.emit('powerSelect',{element});return true;}
    begin(){if(this.blocked()||this.charge)return false;this.charge={at:this.world.time,element:this.selected};if(this.world.demo){this.world.demo=null;this.world.emit('demoEnd');}this.world.emit('powerCharge',{element:this.selected});return true;}
    cancel(){this.charge=null;this.throwHeld=false;}
    request(extra={}){return {element:this.selected,aim:this.aim.active&&this.aim.point?this.aim.point.slice():null,...extra};}
    release(){const c=this.charge;this.charge=null;if(!c||this.blocked())return false;const age=this.world.time-c.at,held=age>=.35,charge=held?C((age-.35)/.8):0,token=c.element==='fire'&&held&&(this.world.player.heat||0)>=35?'m':CASTS[c.element][held?1:0];return this.world.attack(token,false,this.request({element:c.element,charge,held}));}
    quick(kind){if(this.blocked())return false;if(kind==='coat')return this.coat();if(kind==='fusion')return this.world.attack('0',false,this.request());if(kind==='combo')return this.world.attack('@',false,this.request({quick:true}));const map={fire:['f1','f','e'],water:['i','w2','k'],earth:['a','c','l'],wind:['Z','V','Z'],lightning:['L','Q','Q'],stretch:['U','T','R']},index={launch:0,finish:1,heavy:2}[kind];if(index===undefined)return false;let token=map[this.selected][index];if(this.world.grapple?.owner===this.world.player)token=kind==='launch'?'U':kind==='finish'?'G':token;if(kind==='heavy'&&this.selected==='fire'&&(this.world.player.heat||0)>=35)token='m';return this.world.attack(token,false,this.request());}
    comboToken(f,target,element=this.selected){const w=this.world,focus=n=>w.freePlayer()||f.windEnergy>=n,d=Math.hypot(target.x-f.x,target.z-f.z),grip=w.grapple?.owner===f;if(grip)return ['K','P','G'][f.connections.length%3];if(target.down>.08&&w.airHeight(target)<.15)return 'U';if(w.airHeight(target)>.18)return f.airJuggles>=3?'H':/airjab|airhook/.test(f.lastId)?'K':'P';if(w.yard.held(f))return 'P';if(!focus(18))return ['P','K','U'][f.connections.length%3];if(d>2.8)return ({fire:'4',water:'7',earth:'2',wind:'W',lightning:'E',stretch:'S'})[element];if(element==='wind')return f.lastId==='cyclone'?'H':'W';if(element==='lightning')return f.lastId==='arcbolt'?'L':'E';const open=({fire:'d',water:'g',earth:'e1',stretch:'S'})[element],launch=({fire:'f1',water:'i',earth:'a',stretch:'U'})[element];return [open,'P','K',launch][f.connections.length%4];}
    utility(){if(this.blocked())return false;const w=this.world;if(this.selected==='water')return w.elementPhysics.beginSurf();const moving=Math.hypot(w.input.x,w.input.z)>.2,token=this.selected==='earth'?(moving?'b':'l'):({fire:'m',wind:'D',lightning:'L',stretch:'R'})[this.selected];return w.attack(token,false,this.request({terrain:this.selected==='earth'&&moving,utility:true}));}
    coat(){if(this.blocked())return false;if(['wind','stretch'].includes(this.selected)){this.world.emit('elementNotice',{text:'Choose Fire, Water, Earth or Lightning to coat your strikes.'});return false;}return this.world.infusion.coat(this.selected);}
    beginThrow(){const w=this.world;if(this.blocked()||w.grapple?.owner!==w.player||w.grapple.phase!=='clinch'){w.emit('elementNotice',{text:'Catch an opponent first, then hold Power throw and steer the release.'});return false;}this.throwHeld=true;const ok=w.attack('j',false,this.request({throw:true}));if(!ok)this.throwHeld=false;return ok;}
    releaseThrow(){this.throwHeld=false;}
    toggleAim(){this.aim.active=!this.aim.active;if(this.aim.active&&!this.aim.point){const f=this.world.player;this.setAim([f.x+Math.sin(f.angle)*3,0,f.z+Math.cos(f.angle)*3]);}return this.aim.active;}
    setAim(point){if(!Array.isArray(point)||point.length!==3||!point.every(Number.isFinite))return false;const f=this.world.player,dx=point[0]-f.x,dz=point[2]-f.z,n=Math.hypot(dx,dz),scale=n>7?7/n:1;this.aim.point=[C(f.x+dx*scale,-5.8,5.8),Math.max(0,point[1]),C(f.z+dz*scale,-5.3,5.3)];return true;}
    moveAim(x,z,dt){if(Math.hypot(x,z)<.12)return;this.aim.active=true;if(!this.aim.point){const f=this.world.player;this.aim.point=[f.x+Math.sin(f.angle)*3,0,f.z+Math.cos(f.angle)*3];}this.setAim([this.aim.point[0]+x*5*dt,this.aim.point[1],this.aim.point[2]+z*5*dt]);}
    update(){if(this.charge&&this.blocked())this.cancel();if(this.charge&&this.world.time-this.charge.at>=1.3)this.release();}
    onEvent(e){if(e.type==='hurt'||e.type==='envHit'&&e.target==='player'&&e.kind!=='burn'||e.type==='defeat')this.cancel();}
    snapshot(){const w=this.world,charge=this.charge?C((w.time-this.charge.at)/1.15):0;return {selected:this.selected,charging:!!this.charge,charge,primary:LABELS[this.selected][0],held:this.selected==='fire'&&(w.player.heat||0)>=35?'Heat release':LABELS[this.selected][1],aim:{active:this.aim.active,point:this.aim.point?.slice()||null},throwing:!!w.player.action?.move.controlledThrow,throwHeld:this.throwHeld,heat:Math.round(w.player.heat||0),surfing:!!w.elementPhysics.surf};}
  }
  root.CombatPowerControl={PowerControl,ELEMENTS,CASTS,LABELS};if(typeof module!=='undefined'&&module.exports)module.exports=root.CombatPowerControl;
})(typeof window!=='undefined'?window:globalThis);
